  "accroche": "Plage sauvage et préservée aux airs de bout du monde. Un cadre naturel vibrant, ",
  "descLong": "La plage de l'Aubraie est un véritable écrin naturel vendéen, peu fréquenté même en plein été. Son caractère sauvage séduit les amateurs de paysages authentiques : galets doux, dunes et horizons dégagés offrent un cadre visuel saisissant. Accessible à vélo via une piste cyclable, elle se prête à merveille aux pique-niques et aux contemplations face à l'océan. Attention toutefois : la baignade y est déconseillée, voire interdite, en raison de courants dangereux. On y observe crabes et petite faune littorale, et les couchers de soleil y sont tout simplement spectaculaires.",
