  "descLong": "Les Marais Salants de l'Île d'Olonne offrent une escapade naturelle hors du temps, à deux pas des Sables-d'Olonne. Parcourez plus de 7 km de sentiers faciles longeant les anciennes salines, avec pour décor des reflets d'eau, des teintes ocre et rose des bassins, et une faune locale surprenante. La balade débute près d'un magnifique moulin rénové et se prolonge selon les envies grâce à plusieurs itinéraires balisés. Une exposition photo à ciel ouvert enrichit la découverte. Lieu idéal pour se ressourcer dans le calme, accessible à tous, animaux de compagnie bienvenus.",
