  "accroche": "Un sanctuaire sauvage où ciel et mer se rejoignent, bercé par les marées et habi",
  "descLong": "La Réserve Naturelle de la Baie de l'Aiguillon est l'un des sites ornithologiques les plus importants de la façade atlantique française. Vasières, marais salants et prés salés forment un écosystème riche et préservé, rythmé par le ballet incessant des marées. À marée descendante, les oiseaux limicoles et anatidés se rassemblent par milliers pour se nourrir, offrant un spectacle naturel époustouflant. Un chemin de randonnée accessible longe la baie et permet d'observer ce milieu sauvage en toute quiétude, au lever comme au coucher du soleil. Un lieu encore authentique, loin de l'agitation touristique.",
