  "accroche": "Un phare historique au bout de la jetée des Sables-d'Olonne, offrant une vue pan",
  "descLong": "Érigée au XVIIIe siècle, la Petite Jetée des Sables-d'Olonne est bien plus qu'un simple ouvrage portuaire : elle incarne des siècles d'histoire maritime vendéenne. Protégeant le port de l'ensablement, elle fut au XIXe siècle un chemin de halage aux côtés de la Grande Jetée. Aujourd'hui, la promenade le long de cette digue est devenue un incontournable de la ville. Au bout du chemin, le phare offre une vue imprenable sur le Remblai, la Grande Plage et l'horizon atlantique. Accessible aux poussettes et accessible à pied, c'est l'endroit idéal pour une balade en famille ou en amoureux.",
