  "descLong": "Perché sur la corniche de Riez à Saint-Hilaire-de-Riez, le Belvédère Arrondeau offre l'un des panoramas les plus saisissants du littoral vendéen. Une plateforme aménagée permet d'admirer la côte sauvage et, par temps clair, d'apercevoir les côtes de l'île d'Yeu. Des panneaux d'orientation vous aident à identifier les points remarquables du paysage. L'expérience atteint son paroxysme lors des grandes tempêtes : les vagues se fracassent sur les rochers avec une puissance spectaculaire. À deux pas, le célèbre Trou du Diable et son geyser naturel complètent parfaitement cette escapade sur la corniche. Accessible aux poussettes et fauteuils roulants.",
