  "descLong": "Le Puits d'Enfer est une curiosité naturelle saisissante de la côte vendéenne : une faille creusée dans la roche où les vagues s'engouffrent avec une force impressionnante. Le spectacle change radicalement selon le coefficient de marée — plus il est élevé (au-delà de 90), plus la houle gronde, l'écume jaillit et les embruns envahissent l'air. Idéal à observer à marée montante ou haute par fort coefficient, ce site chargé de légendes offre aussi une belle promenade sur les rochers par temps calme. Un lieu où la nature vendéenne révèle toute sa puissance brute.",
