  "descLong": "Le Remblai est la promenade emblématique des Sables-d'Olonne, s'étirant sur plus de 2 kilomètres en bord de mer. Face à l'immensité de l'océan Atlantique, ce boulevard animé offre une vue à couper le souffle sur les vagues et la Grande Plage. Bordé de restaurants, glaciers et boutiques, il est le cœur battant de la ville estivale. Au nord, la jetée ferme l'horizon tandis qu'au sud le quartier de la Chaume apporte une touche authentique. Idéal pour flâner au lever du soleil, profiter d'un coucher de soleil enflammé ou simplement savourer une glace les pieds dans le sable.",
