  "descLong": "Le Chemin des Douaniers relie Cayola à Bourgenay le long d'une côte sauvage et préservée de la Vendée. Ce sentier longe les falaises qui surplombent l'océan Atlantique, offrant des panoramas à couper le souffle sur la mer et les paysages littoraux. Balisé et bien stabilisé, il se parcourt facilement en famille ou en couple. Les amateurs de nature apprécieront la végétation côtière typique, les points de vue sur les rochers et les criques, ainsi que la quiétude des lieux, surtout en dehors de la haute saison. Un incontournable de la côte sud-vendéenne, accessible aux chiens en laisse.",
