  "descLong": "Le port de La Chaume, niché à l'entrée du chenal des Sables-d'Olonne, est un lieu chargé d'histoire maritime et d'émotions sportives. C'est ici que les skippers du Vendée Globe franchissent la ligne d'arrivée après leur tour du monde en solitaire, sous les acclamations de milliers de spectateurs. Le quai Alain Gerbaud rend hommage aux grands navigateurs qui ont marqué l'histoire de la voile. Entre bateaux de pêche colorés, odeurs iodées et animations nautiques, le port offre une atmosphère authentique et vivante. Une navette maritime à prix modique permet de rejoindre facilement le centre des Sables-d'Olonne, parfaite pour explorer les deux rives.",
