  "descLong": "Le dolmen de la Frébouchère, niché près du bourg de Le Bernard, est l'un des mégalithes les plus impressionnants de Vendée. Datant d'environ 4000 ans avant J.-C., il se distingue par ses dimensions remarquables : 7,20 mètres de longueur et 3,50 mètres de hauteur, couverts par seulement deux pierres de couverture. Le site est parfaitement aménagé, avec une signalétique claire et un parking à proximité. Dans un rayon d'un kilomètre, plusieurs autres dolmens complètent la visite, faisant de ce secteur un véritable sanctuaire mégalithique vendéen accessible à tous, y compris aux personnes à mobilité réduite.",
