  "descLong": "Vouvant est un joyau médiéval niché au cœur du bocage vendéen, classé parmi Les Plus Beaux Villages de France depuis 1988. Ancienne place forte, le village a conservé une grande partie de ses fortifications, ses ruelles pavées et son architecture d'antan. Dominé par la tour Mélusine, vestige imposant d'un château du XIe siècle, Vouvant offre un voyage dans le temps saisissant. Flânez entre les maisons de pierre, découvrez l'église romane Notre-Dame et profitez des panoramas sur les vallées boisées environnantes. Un village à vivre lentement, au fil des saisons.",
